    var M = {"john":{"fr":"« Yahvé fait grâce »"},"mary":{"fr":"Incertain — « bien-aimée », « amertume » ou « enfant désiré »"},"muhammad":{"fr":"« Le loué », « digne de louange »"},"alexander":{"fr":"« Défenseur des hommes » (aléxō « défendre » + anḗr « homme »)"},"joseph":{"fr":"« Il ajoutera » / « que Dieu ajoute »"},"michael":{"fr":"« Qui est comme Dieu ? »"},"george":{"fr":"« Agriculteur, travailleur de la terre » (gē « terre » + ergon « travail »)"},"sophia":{"fr":"« Sagesse »"},"fatima":{"fr":"« Celle qui sevre / s’abstient » (racine f-ṭ-m)"},"ali":{"fr":"« Haut, élevé, sublime » (racine ʿ-l-w)"},"krishna":{"fr":"« Sombre, noir » (d’après le teint bleu-noir de la divinité)"},"rama":{"fr":"« Agréable, charmant, délicieux » (racine ram- « plaire, ravir »)"},"david":{"fr":"« Bien-aimé »"},"daniel":{"fr":"« Dieu est mon juge » (dān « juger » + ʼēl « Dieu »)"},"peter":{"fr":"« Roc, pierre » — forgé par Jésus pour rendre l’araméen Kēfā"},"paul":{"fr":"« Petit, humble »"},"thomas":{"fr":"« Jumeau »"},"abraham":{"fr":"« Père dʼune multitude de nations »"},"isaac":{"fr":"« Il rit » / « il rira »"},"jacob":{"fr":"« Supplanteur », « celui qui tient le talon »"},"moses":{"fr":"« Tiré des eaux » (traditionnel)"},"solomon":{"fr":"« Paix » (de shalom)"},"matthew":{"fr":"« Don de Yahvé »"},"adam":{"fr":"« Homme ; humanité », de adamah « terre, sol »"},"noah":{"fr":"« Repos, réconfort »"},"gabriel":{"fr":"« Dieu est ma force »"},"elijah":{"fr":"« Mon Dieu est Yahvé »"},"sarah":{"fr":"« Princesse, femme noble »"},"anna":{"fr":"« Grâce, faveur »"},"elizabeth":{"fr":"« Mon Dieu est un serment »"},"omar":{"fr":"« Longévité, florissant, prospère »"},"aisha":{"fr":"« Vivante, pleine de vie, prospère »"},"khadija":{"fr":"« Née avant terme, enfant prématurée »"},"abdullah":{"fr":"« Serviteur de Dieu »"},"hassan":{"fr":"« Bon, beau, magnifique »"},"husayn":{"fr":"« Petit Hasan », « le petit être magnifique »"},"zaynab":{"fr":"Une plante du désert odorante et fleurie"},"nicholas":{"fr":"« Victoire du peuple »"},"helen":{"fr":"Incertain — probablement « torche, celle qui brille »"},"catherine":{"fr":"Incertain — rattaché par étymologie populaire à « pur »"},"margaret":{"fr":"« Perle »"},"philip":{"fr":"« Ami des chevaux »"},"theodore":{"fr":"« Don de Dieu »"},"anthony":{"fr":"Un nom de gens romain dʼorigine incertaine, peut-être étrusque"},"julia":{"fr":"« Jeune » ; forme féminine du nom de gens Iulius, liée à Jupiter"},"lakshmi":{"fr":"« Signe, marque » → « bonne fortune, prospérité »"},"arjun":{"fr":"« Brillant, blanc, argenté, clair »"},"sita":{"fr":"« Sillon » (la ligne tracée par la charrue)"},"ganesh":{"fr":"« Seigneur des ganas (les troupes, la multitude) »"},"priya":{"fr":"« Bien-aimée, chère »"}};
    var B = {"john":{"fr":"L’un des noms les plus répandus sur Terre. L’hébreu Yōḥānān, porté par John the Baptist et John the Apostle, est passé en grec sous la forme Iōánnēs et en latin sous la forme Iohannes, avant de se répandre dans toute la chrétienté. L’Europe occidentale a conservé le J/G initial (John, Jean, Juan, Giovanni) ; le monde slave oriental l’a remodelé en Ivan ; et le Qurʼan conserve une forme arabe parallèle, Yaḥyā, pour le même prophète."},"mary":{"fr":"Le nom de la mère de Jésus et de Miriam, sœur de Moïse, et par elles l’un des noms féminins les plus vénérés au monde. Le grec Maria et le latin Maria l’ont répandu dans toutes les langues chrétiennes ; le Qurʼan donne Maryam, la seule femme qui y soit nommée, si bien que ce nom est tout aussi central dans le monde islamique."},"muhammad":{"fr":"Le nom du Prophète de l’islam et, selon bien des décomptes, le prénom masculin le plus répandu sur Terre. De l’arabe muḥammad (racine ḥ-m-d, « louer »), il a voyagé avec l’islam dans toutes les langues du monde musulman, chacune en remodelant les sons : Mehmet en turc, Mohammad en persan/ourdou, Muhamed en bosnien, Mamadou en Afrique de l’Ouest, Muhammad/Mohd en Asie du Sud-Est."},"alexander":{"fr":"Porté sur trois continents par Alexander le Grand, dont les conquêtes ont implanté le nom de la Grèce à l’Inde. Le christianisme le diffusa ensuite plus largement à travers saints et papes. Il se raccourcit affectueusement presque partout — Alex, Sasha, Sander, Xander, Ale, Iskandar — et entra même dans le monde islamique sous la forme Iskandar/Sikandar."},"joseph":{"fr":"Le nom du patriarche Joseph, vendu en Égypte, et de saint Joseph, époux de Mary. L’hébreu Yōsēf est passé par le grec Iōsḗph et le latin Ioseph dans toutes les langues chrétiennes, se contractant en José en Ibérie, Giuseppe en Italie et Josef dans les mondes germanique et slave. Le Qurʼan raconte l’histoire du même patriarche sous la forme arabe parallèle Yūsuf, qui s’est répandue avec l’islam de l’Afrique de l’Ouest à l’Indonésie."},"michael":{"fr":"À l’origine le nom de l’archange Michael, chef guerrier de l’armée céleste, dont le culte porta le nom à travers toute la chrétienté. Le grec Michaḗl et le latin Michael se ramifièrent en Michel, Miguel, Michele, Michael et le slave Mikhail, adoucissant au passage la gutturale hébraïque ḵ en un son k ou h. Le Qurʼan nomme le même ange Mīkāʼīl, donnant une forme islamique parallèle en usage de l’Iran à l’Afrique de l’Ouest."},"george":{"fr":"Du grec Geōrgios, formé sur geōrgós « paysan, laboureur », le nom doit sa vaste diffusion à Saint George, le martyr tueur de dragon vénéré dans toute la chrétienté et patron de l’Angleterre, de la Géorgie et de l’Éthiopie. Il se déploie en Jorge, Giorgio, Georg et Jerzy, et le monde slave oriental l’a scindé en deux prénoms bien vivants — le savant Georgy et le quotidien Yuri. Dans le Caucase, c’est un favori national : le géorgien Giorgi et l’arménien Gevorg."},"sophia":{"fr":"Le grec sophía signifie tout simplement « sagesse », personnifiée en vertu et consacrée dans la grande église Hagia Sophia de Constantinople, « Sainte Sagesse ». Porté par la tradition byzantine et orthodoxe et arboré par des impératrices et des saintes, il s’est répandu sous les formes Sofia, Sophie, Zsófia et Zofia. Aujourd’hui, c’est l’un des prénoms de filles les plus populaires au monde, en tête des registres de naissance à travers l’Europe et les Amériques ; le russe lui donne le tendre diminutif Sonya."},"fatima":{"fr":"Le nom de Fāṭima al-Zahrāʼ, fille du Prophète Muhammad et épouse de ʿAlī, et donc l’un des prénoms féminins les plus honorés de l’islam — surtout dans la tradition chiite, où elle est la mère des imams. Issu de la racine arabe f-ṭ-m (« sevrer »), il s’est répandu avec l’islam et s’est adouci en chemin : le turc l’abrège en Fatma, le persan en arrondit la finale en Fāṭeme, et l’Asie du Sud et du Sud-Est conservent la forme plus pleine Fatimah. Dans les Balkans, il survit sous la forme Fatima avec le diminutif Fata."},"ali":{"fr":"Le nom de ʿAlī ibn Abī Ṭālib, cousin et gendre du Prophète Muhammad, quatrième calife dans la tradition sunnite et premier imam de l’islam chiite — ce qui fait d’Ali l’un des noms centraux du monde musulman, et aussi l’un des « beaux noms », puisque al-ʿAlī est un attribut de Dieu. De l’arabe ʿAlī (racine ʿ-l-w, « être élevé »), les sons se transmettent presque inchangés d’une langue à l’autre : Ali en turc et en persan, Ali en ourdou, Alija en bosniaque, Aliyu en Afrique de l’Ouest. En Occident, il est surtout connu grâce au boxeur Muhammad Ali."},"krishna":{"fr":"Krishna est le huitième avatar de Vishnu et l’une des divinités les plus aimées de l’hindouisme — le bouvier joueur de flûte de Vrindavan et le sage cocher de la Bhagavad Gita. Le sanskrit kṛṣṇa signifie littéralement « sombre, noir », décrivant son teint, et a donné des formes affectueuses comme Kanha et le tamoul Kannan. Comme prénom, il est répandu dans toute l’Inde et dans l’ensemble de la diaspora hindoue ; sa diffusion en Asie du Sud-Est passe par le théâtre d’ombres wayang et le Mahabharata."},"rama":{"fr":"Rama est un avatar de Vishnu et le héros du Ramayana, le roi idéal d’Ayodhya dont l’histoire compte parmi les plus racontées au monde. Le sanskrit rāma signifie « plaisant, charmant ». Ce fut surtout l’épopée qui porta le nom à travers l’Asie du Sud-Est : les rois thaïlandais de la dynastie Chakri prennent tous le nom de règne de Rama, Ayutthaya elle-même fut nommée d’après Ayodhya, lieu de naissance de Rama, et Rama subsiste dans le Reamker cambodgien (sous le nom de Preah Ream), le wayang javanais et balinais, et le Phra Lak Phra Ram laotien."},"david":{"fr":"Le nom du roi-berger d’Israël, deuxième roi et vainqueur de Goliath, vénéré aussi bien dans le judaïsme que dans le christianisme et l’islam. L’hébreu Dāwīḏ est passé par le grec et le latin dans toutes les langues européennes presque sans changement, tandis que le géorgien Davit et l’éthiopien Dawit sont devenus des noms royaux à part entière. Parce que David est aussi un prophète du Qurʼan, une lignée islamique parallèle court à travers l’arabe Dāwūd — Daud, Davut, Daudi — dans tout le monde musulman."},"daniel":{"fr":"D’après le prophète visionnaire du Livre de Daniel, dont la foi dans la fosse aux lions a fait de ce nom un symbole de constance. L’hébreu Dāniyyēl est passé par le grec Daniḗl et le latin Daniel dans l’Occident chrétien, en gardant une orthographe remarquablement stable, tandis que le monde slave l’a remodelé en Daniil et Danylo. Daniel est aussi honoré dans la tradition islamique sous le nom du prophète Dāniyāl, dont le tombeau à Suse demeure un lieu de pèlerinage."},"peter":{"fr":"Le nom que Jésus donna au pêcheur Simon — le grec Pétros, « roc », traduction du surnom araméen Kēfā — faisant de lui le roc sur lequel l’Église fut bâtie. Premier pape, saint Pierre porta le nom dans toutes les terres chrétiennes : latin Petrus, français Pierre, espagnol Pedro, italien Pietro, russe Pyotr. Les chrétiens d’Orient conservèrent le grec Petros, et les chrétiens arabophones disent Buṭrus."},"paul":{"fr":"Le cognomen romain Paulus, « petit », que reprit lʼapôtre Paul — né Saul de Tarse — dont les épîtres façonnèrent la théologie chrétienne et portèrent son nom à travers le monde. Les Églises de langue grecque le connaissaient sous le nom de Paûlos, et du latin Paulus vinrent Pablo, Paolo, Paulo, Paweł et le slave Pavel. Lʼarménien le remodela de façon frappante en Poġos, et les chrétiens arabophones lʼappellent Būlus."},"thomas":{"fr":"Le surnom de lʼapôtre qui douta de la Résurrection jusquʼà ce quʼil touchât les plaies du Christ — araméen Tʼōmā, « jumeau », que les Évangiles grecs traduisent aussi par Dídymos. À travers le grec Thōmâs et le latin Thomas, il se répandit vers lʼouest sous les formes Thomas, Tomás, Tommaso et Tomasz, tandis que lʼorient slave le remodela en Foma et Khoma. Les chrétiens arabophones conservent la sonorité araméenne sous la forme Tūmā."},"abraham":{"fr":"Le patriarche vénéré comme le père des croyants dans les trois religions abrahamiques. Lʼhébreu Avraham, « père dʼune multitude de nations », passa par le grec Abraám et le latin Abraham dans lʼOccident chrétien, tandis que le Qurʼan donne la forme parallèle Ibrāhīm — lʼun des prénoms masculins les plus répandus dans tout le monde musulman, du Maroc à lʼIndonésie. Le néerlandais lʼabrège en Bram ; le Caucase le remodèle en Ibragim."},"isaac":{"fr":"Le fils dʼAbraham et deuxième patriarche, dont le nom hébreu Yitzḥaq signifie « il rit ». Le grec Isaák et le latin Isaac le portèrent vers lʼouest — italien Isacco, allemand et russe Isaak —, tandis que le Qurʼan nomme le même prophète Isḥāq. Prénom apprécié des familles juives, chrétiennes et musulmanes à la fois, il fut porté par des figures allant dʼIsaac Newton à lʼécrivain russe Isaak Babel."},"jacob":{"fr":"Le troisième patriarche, rebaptisé plus tard Israël ; son nom hébreu Yaʿaqov donna naissance à lʼun des arbres généalogiques les plus enchevêtrés de toute lʼonomastique. Le latin Iacobus produisit Jacob, Jakob et le slave Yakov, mais une variante du latin vulgaire, Iacomus, se détacha pour devenir lʼitalien Giacomo, le français Jacques, lʼanglais James, ainsi que les ibériques Diego, Santiago, Tiago et Jaime — tous des doublets dʼun seul et même nom. Le Qurʼan conserve le prophète sous le nom de Yaʻqūb."},"moses":{"fr":"Le prophète qui conduisit les Israélites hors dʼÉgypte ; son nom hébreu Mosheh est traditionnellement interprété comme « tiré des eaux ». Par le grec Mōÿsês et le latin Moyses, il se répandit sous la forme Moses, français Moïse, espagnol Moisés et italien Mosè, tandis que Mūsā — nommé dans le Qurʼan plus souvent que tout autre prophète — devint lʼun des grands noms du monde musulman, porté par lʼempereur du Mali Mansa Musa."},"solomon":{"fr":"Le roi sage, fils de David ; son nom hébreu Shlomoh dérive de shalom, « paix ». Le grec Solomṓn et le latin Salomon donnèrent Solomon, le français Salomon, lʼitalien Salomone et le portugais Salomão. Les empereurs dʼÉthiopie se réclamaient de lui dans la dynastie salomonienne, et le Qurʼan lʼhonore comme le roi-prophète Sulaymān — à lʼorigine du turc Süleyman, porté par le plus grand des sultans ottomans."},"matthew":{"fr":"Le nom de lʼapôtre et évangéliste Matthew, le collecteur dʼimpôts appelé par Jésus et auteur traditionnel du premier Évangile. Lʼhébreu Mattityāhū (« don de Yahweh ») fut abrégé en grec en Maththaîos et latinisé en Matthaeus, puis se répandit dans toute la chrétienté sous les formes Matteo, Mateo, Matthieu, Mateusz et le slave Matvei. Les chrétiens arabophones connaissent lʼévangéliste sous le nom de Mattā."},"adam":{"fr":"Le nom du premier homme, façonné de la terre dans la Genèse et nommé vingt-cinq fois dans le Qurʼan, et donc partagé par les juifs, les chrétiens et les musulmans. Fait rare, il ne demande presque aucune transformation dʼune langue à lʼautre — Adam en anglais, allemand, polonais et arabe, Adán en espagnol, Adamo en italien, Adem en turc et en bosniaque, Adamu en haoussa et en swahili. Dans le monde islamique, Ādam est un prénom très courant au quotidien."},"noah":{"fr":"Le constructeur de lʼarche qui survécut au Déluge, honoré aussi bien dans la Bible que dans le Qurʼan. Lʼhébreu Nōaḥ passa par le grec Nôe et le latin Noe pour donner le roman Noé et lʼitalien Noè, tandis que lʼanglais conserva la forme plus complète Noah. Au vingt et unième siècle, Noah sʼest hissé en tête des prénoms masculins aux États-Unis et dans toute lʼEurope, et a même été réemprunté au Japon sous le nom moderne Noa. Le Qurʼan raconte la même histoire sous la forme arabe parallèle Nūḥ, lʼun des cinq plus grands prophètes de lʼislam."},"gabriel":{"fr":"Le nom de lʼarchange qui révèle des visions à Daniel, annonce la naissance de John et de Jesus, et qui dans lʼislam dicte le Qurʼan à Muhammad. Lʼhébreu Gaḇrīʼēl est devenu le grec Gabriḗl et le latin Gabriel, restant proche de sa source en français, espagnol, portugais et allemand, sʼadoucissant en Gabriele en italien et en Gavriil / Gavrilo dans les langues slaves. Le Qurʼan nomme ce même ange Jibrīl, et en Éthiopie lʼarchange Gabrʼel est profondément vénéré."},"elijah":{"fr":"Le nom du prophète fougueux du IXe siècle av. J.-C. qui affronta les prêtres de Baal sur le mont Carmel et fut enlevé au ciel dans un tourbillon. Dans le grec du Nouveau Testament, il est Ēlías, qui a donné le latin Elias et les nombreuses formes européennes Elias / Élie / Ilie, tandis que le monde slave oriental en a fait le quotidien Ilya. La forme plus complète Elijah est devenue un prénom anglais moderne de tout premier rang. Le Qurʼan honore le même prophète sous la forme arabe parallèle Ilyās."},"sarah":{"fr":"Le nom de lʼépouse du patriarche Abraham, qui dans la Genèse est rebaptisée de Sarai en Sarah, « princesse ». Le grec Sárra et le latin Sara le portèrent à travers le monde chrétien, où il devint lʼun des prénoms féminins les plus populaires de lʼépoque moderne. Comme Abraham est un patriarche commun, le même nom se perpétue dans le monde musulman sous la forme Sāra, et il varie affectueusement de Zara au finnois Saara."},"anna":{"fr":"De lʼhébreu Ḥannāh, la mère du prophète Samuel — un nom qui signifie « grâce ». Le grec le rendit Ánna — porté dans lʼÉvangile de Luc par la prophétesse Anna — et par le latin il devint lʼun des prénoms féminins les plus répandus dʼEurope, honoré de surcroît comme le nom de sainte Anne, mère de la Vierge Mary. Lʼanglais conserve à la fois Anna, issu du grec, et Hannah, restauré depuis lʼhébreu, comme un doublet, et le même personnage apparaît dans lʼislam sous le nom de Ḥanna, la mère de Mary."},"elizabeth":{"fr":"De lʼhébreu Elišévaʿ, la femme dʼAaron et, dans lʼÉvangile de Luc, la mère de John le Baptiste. Le grec Elisábet et le latin Elisabeth le répandirent dans toute la chrétienté, où il fut porté par des saints et par une longue lignée de reines, avant tout Elizabeth I et Elizabeth II dʼAngleterre. Dans la péninsule Ibérique, le même nom fut remodelé en un célèbre rejeton, Isabel (italien Isabella), tandis que les mondes slave et hongrois lui donnèrent Yelizaveta et Erzsébet."},"omar":{"fr":"Porté par ʿUmar ibn al-Khattāb, compagnon du Prophète et deuxième calife rāshidūn dont le règne façonna le premier État islamique, ʿUmar est lʼun des prénoms masculins classiques du monde musulman. Issu de la racine arabe ʿ-m-r (« vivre, prospérer »), il signifie « qui vit longtemps, prospère ». Il sʼest transformé en Ömer turc et Omer bosniaque, et a gagné lʼOccident par des porteurs tels quʼOmar Sharif. Un prénom hébreu sans rapport, Omar — un petit-fils dʼÉsaü dans la Genèse — nʼest quʼune coïncidence sonore distincte."},"aisha":{"fr":"Le prénom de ʿĀʼisha bint Abī Bakr, épouse du Prophète Muhammad réputée comme savante et transmettrice de hadiths, ce qui en a fait lʼun des prénoms féminins les plus populaires de tout le monde musulman. Issu de la racine arabe ʿ-y-sh (« vivre »), il signifie « vivante, en vie ». Le turc lʼa transformé en Ayşe — longtemps le prénom féminin le plus répandu de Turquie —, tandis que lʼusage maghrébin donne Aïcha et lʼAsie du Sud Ayesha. Ces dernières décennies, il sʼest aussi largement classé au Royaume-Uni, en France et aux États-Unis."},"khadija":{"fr":"Khadīja bint Khuwaylid fut la première épouse du Prophète Muhammad, une riche marchande de La Mecque et la première personne à embrasser lʼislam ; son nom est chéri depuis lors. Il dérive de la racine arabe kh-d-j, associée à un enfant « né tôt » ou prématuré. Le turc le porte sous la forme Hatice, lʼAfrique de lʼOuest sous le haoussa Hadiza et le sénégalais Khady, et le swahili sous Hadija. Avec Fatima et Aisha, il compte parmi les prénoms féminins les plus répandus du monde musulman."},"abdullah":{"fr":"Un prénom théophore signifiant « serviteur de Dieu », formé de ʿabd (« serviteur ») et Allāh. Ce fut le nom du père du Prophète Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, et un hadith désigne ʿAbdullāh et ʿAbd al-Rahmān comme les noms les plus aimés de Dieu — il compte donc parmi les prénoms les plus recommandés en islam. Il parcourt le monde musulman avec de légères variations phonétiques : Abdollah en persan, Abdallah et Abdellah au Maghreb, Abdullahi au Nigeria, Abdoulaye en Afrique de lʼOuest francophone et Abdulah en Bosnie."},"hassan":{"fr":"Ḥasan (racine ḥ-s-n, « être bon, beau ») était le nom de Hasan ibn Ali, petit-fils aîné du Prophète Muhammad et deuxième imam chiite. Il est presque toujours associé au nom de son frère cadet — Hasan et Husayn ensemble. Porté par lʼislam à travers le monde, il a conservé une forme remarquablement stable (Hasan en turc, Hasan/Haso en bosniaque) et demeure lʼun des prénoms masculins les plus répandus du monde musulman."},"husayn":{"fr":"Ḥusayn est le diminutif de Ḥasan — « petit Hasan », « le petit être magnifique ». Il fut porté par Husayn ibn Ali, petit-fils cadet du Prophète, dont le martyre à la bataille de Kerbala en 680 apr. J.-C. fit de ce nom le cœur émotionnel de l’islam chiite, commémoré chaque année lors de l’Achoura. Ses formes parcourent le monde musulman : le persan Hossein, le turc Hüseyin, le Hussain sud-asiatique et le Hussein arabe que portèrent Saddam Hussein et le roi Hussein de Jordanie."},"zaynab":{"fr":"Zaynab est le nom d’une plante du désert parfumée et fleurie. Il fut porté par une fille du Prophète Muhammad, Zaynab bint Muhammad, et par sa petite-fille Zaynab bint Ali, sœur de Husayn et héroïne vénérée de la tragédie de Kerbala. Le nom prospère dans tout le monde musulman, surtout sous la forme turque Zeynep — durant des années le prénom féminin le plus populaire de Turquie — et sous la forme ouest-africaine Zenabou."},"nicholas":{"fr":"Du grec Nikólaos, « victoire du peuple », répandu à travers la chrétienté par le culte de saint Nicholas de Myre — l’évêque du IVe siècle dont la légende des cadeaux devint Santa Claus, nom lui-même usé à partir du néerlandais Sinterklaas. Presque partout il se raccourcit affectueusement : Klaus en allemand, Klaas en néerlandais, Nikos en grec, Kolya en russe. L’Europe de l’Est le remodela en Nikolai, Mykola et Mikuláš, tandis que la Hongrie en fit Miklós."},"helen":{"fr":"La forme anglaise du grec Helénē, sans doute d’un mot signifiant « torche » ou « la brillante ». Portée par Helen de Troie, dont la beauté aurait « lancé mille navires », et par sainte Helena, mère de l’empereur Constantine, à qui l’on attribue la découverte de la Vraie Croix. À travers le latin Helena, elle devint Elena dans les mondes roman et slave méridional et Yelena / Olena à l’est, tandis que le hongrois la remodela en Ilona."},"catherine":{"fr":"Du grec Aikaterínē, très tôt rattaché par étymologie populaire à katharós, « pur », ce qui fixa la graphie en -th- en Occident. Répandu par le culte extrêmement populaire de sainte Catherine d’Alexandrie, il devint l’un des prénoms féminins les plus portés d’Europe, par des reines et des impératrices, de Catherine de Medici à Catherine the Great. Il se raccourcit en toute une garde-robe de diminutifs — Kate, Katie, Katya, Kasia — dont l’un, le Karin allemand et suédois, est homophone d’un prénom de fille japonais."},"margaret":{"fr":"Du grec margarítēs (« perle »), un mot que le grec avait lui-même emprunté à un Orient plus lointain. Le culte de sainte Marguerite dʼAntioche en fit un prénom prisé dans toute lʼEurope médiévale, porté ensuite par des reines et par des figures allant de Margaret Thatcher à Margaret Atwood. Ses diminutifs ont pris leur propre essor — Greta en allemand, Rita en italien et en espagnol, et Daisy en anglais, puisque le français marguerite en est venu à désigner la fleur."},"philip":{"fr":"Du grec Phílippos (« ami des chevaux »), nom de la royauté macédonienne porté par Philip II, père dʼAlexandre le Grand. Nom dʼun apôtre, il se répandit dans toute la chrétienté et devint cher aux rois ibériques — six Felipe espagnols et plusieurs Filipe portugais, dont les Philippines tirent leur nom. Les Britanniques le connaissent surtout à travers Prince Philip, feu le duc dʼÉdimbourg."},"theodore":{"fr":"Du grec Theódōros (« don de Dieu »), image inversée de Dorothée. Porté par de nombreux saints des premiers temps, il sʼenracina dans toute lʼEurope et au-delà — le russe Fyodor de Dostoïevski et lʼéthiopien Tewodros. En anglais, il séduit par ses diminutifs Ted, Teddy et Theo."},"anthony":{"fr":"Du nom de famille romain Antōnius, une ancienne gens peut-être dʼorigine étrusque dont le membre le plus tristement célèbre fut Mark Antony (Marcus Antōnius). Les nombreux saints nommés Anthony — surtout Antoine le Grand et Antoine de Padoue — le portèrent à travers la chrétienté, où Antonio devint lʼun des prénoms les plus répandus dʼItalie et de la péninsule Ibérique. Lʼorthographe avec un h reflète un rapprochement ultérieur et erroné avec le grec ánthos (« fleur »)."},"julia":{"fr":"Le féminin du nom de gens romain Iūlius, la famille de Jules César et de lʼempereur Auguste, ce qui fit dʼIūlia lʼun des grands noms de la dynastie julio-claudienne — la fille de César comme la fille dʼAuguste se nommaient Julia. Longtemps aussi nom dʼune sainte chrétienne, cʼest aujourdʼhui lʼun des prénoms de filles les plus populaires dʼEurope et des Amériques. Son pendant masculin subsiste sous les formes Julius, Julio et Jules."},"lakshmi":{"fr":"Lakshmi est la déesse hindoue de la richesse, de la fortune et de la beauté, et lʼépouse de Vishnu, dont elle prend une forme assortie auprès de chacun de ses avatars. Le sanskrit lakṣmī dérive de lakṣ « marquer, percevoir », dʼoù le sens dʼun signe de bon augure et, par extension, de prospérité. On lʼhonore avant tout à Diwali, et son nom est lʼun des prénoms féminins les plus répandus dans tout le sud de lʼInde — même si des composés comme Lakshmi Narayan et des patronymes comme Mittal le portent aussi pour les hommes. Au Bengale, la déesse comme le nom se prononcent Lokkhi."},"arjun":{"fr":"Arjuna est le héros-archer du Mahabharata — le troisième des cinq frères Pandava, fils du dieu Indra, et le guerrier à qui Krishna délivre la Bhagavad Gita sur le champ de bataille de Kurukshetra. Le sanskrit arjuna signifie « brillant, argenté, blanc ». Sous la forme Arjun, cʼest lʼun des prénoms masculins les plus populaires de lʼInde actuelle, et lʼépopée a porté le personnage jusquʼen Asie du Sud-Est, où le raffiné ksatriya Arjuna (Janaka en javanais) est un favori du théâtre dʼombres wayang."},"sita":{"fr":"Sita est lʼhéroïne du Ramayana et lʼépouse de Rama, un avatar de Lakshmi et lʼidéal même de la vertu, de la dévotion et de la constance. Son nom sanskrit signifie « sillon » : le roi Janaka la trouva dans un champ labouré, fille de la déesse de la terre Bhumi. Lʼépopée la répandit dans toute lʼAsie du Sud-Est — elle est Nang Sida (นางสีดา) dans le Ramakien thaï, Sinta ou Shinta dans le wayang javanais, et Neang Seda dans le Reamker cambodgien."},"ganesh":{"fr":"Ganesha est le fils à tête dʼéléphant de Shiva et de Parvati, le bien-aimé qui écarte les obstacles et le patron des commencements, du savoir et des arts, quʼon invoque avant toute entreprise nouvelle. Son nom sanskrit joint gaṇa « troupes, cohortes » à īśa « seigneur », et il est tout aussi connu sous les noms de Vinayaka et Ganapati. Sous la forme Ganesh, cʼest un prénom masculin courant en Inde, et la divinité sʼest répandue dans toute lʼAsie du Sud-Est — vénérée en Thaïlande sous le nom de Phra Phikhanet (พระพิฆเนศ), patron des arts, et en Indonésie sous celui de Ganesha, dont lʼimage est lʼemblème de lʼInstitut de technologie de Bandung (ITB)."},"priya":{"fr":"Priya nʼest pas un nom de divinité mais un prénom à part entière — le féminin du sanskrit priya « aimé, cher », de la racine prī « plaire ». Cʼest lʼun des prénoms féminins les plus répandus aujourdʼhui en Inde, au Népal, au Bangladesh et au Sri Lanka, et il gagne aisément la diaspora en tant que forme sympathique et facile à prononcer. En tamoul, le masculin Priyan ou Priya sʼemploie aussi pour les hommes. La racine est ancienne : elle est apparentée au nom de la déesse germanique Frigg, tous deux issus de lʼindo-européen commun *priH- « aimé »."}};
